// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor is the actor who deposits and then calls withdrawAll; amount is the deposit value
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep deposit amount in a reasonable non-zero range
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy an attacker who will reenter on receiving funds
        Attacker attacker = new Attacker(address(c));

        // fund depositor and attacker
        vm.deal(depositor, amount);
        vm.deal(address(attacker), 1 ether);

        // depositor deposits into C
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now we will have the attacker take the depositor's role by having the attacker set itself as msg.sender
        // The attacker will first deposit (so it has credit), then when it calls withdrawAll it will reenter to try to
        // exploit the mutant ordering. We want to assert that after withdrawAll completes, the depositor's (attacker's)
        // credit in the contract is zero. This holds for the reference but the mutant can leave it non-zero.

        // attacker deposits same amount to have credit and be able to trigger withdraw
        attacker.deposit{value: amount}();

        // attacker triggers withdrawAll which will reenter on mutant; we call via attacker to ensure fallback runs
        bool ok;
        try attacker.doWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: after withdrawAll finishes, the contract's recorded credit for attacker must be zero
        // We observe via the auto getter for the mapping: credit is not publicly declared in source file but assuming the
        // reference exposes no getter; however per problem statement we must observe only public surfaces. To read credit,
        // we instead rely on the fact that when credit is zero, withdrawAll won't send any more funds; but we need a direct
        // public observation. The contract C as given has no public getter for credit; however address(c).balance reflects
        // funds held. For the invariant we assert that after attacker.withdrawAll, the contract balance decreased by exactly the
        // withdrawn amount (i.e., equals initial balance minus amount). To be precise and universal across inputs, we check
        // that address(c).balance <= type(uint256).max (tautology) — not allowed. Instead, the safe observable is that calling
        // withdrawAll a second time does not send more funds (i.e., it succeeds but sends zero). We implement this by having the
        // attacker's fallback revert if it receives non-zero value on the second reentrant attempt; the reference will not attempt
        // to send again so the call succeeds. To conform to the single assert rule, we call withdrawAll a second time and assert
        // that it does not transfer funds (i.e., call returns ok). We capture its success via try/catch on attacker.doWithdrawSecond.

        // perform second withdraw attempt via attacker; in the reference this will do nothing and return true; in the mutant
        // reentrancy could have left credit non-zero and cause another transfer which our attacker will detect and revert.
        bool ok2;
        try attacker.doWithdrawSecond() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The universal property: the second withdrawAttempt should succeed (i.e., not trigger a transfer that makes attacker revert).
        // Reference contract satisfies this for all inputs; the mutant can fail for some inputs (attacker detects extra transfer and reverts).
        assertTrue(ok2);
    }
}

// Minimal attacker that will revert if it receives Ether on the second withdraw (detecting unexpected extra transfer)
contract Attacker {
    C c;
    bool firstReceive;
    constructor(address _c) {
        c = C(_c);
        firstReceive = true;
    }

    // deposit helper
    function deposit() external payable {
        // forward deposit to C
        (bool ok, ) = address(c).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // trigger withdrawAll via this contract so fallback/run can reenter
    function doWithdraw() external {
        // call c.withdrawAll
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        require(ok);
    }

    // second attempt: this will detect if C tries to send Ether again by reverting on receive
    function doWithdrawSecond() external returns (bool) {
        // mark that subsequent receive should revert
        firstReceive = false;
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        return ok;
    }

    receive() external payable {
        // On first receive (during first withdraw) accept funds and reenter once to drain if mutant allows
        if (firstReceive) {
            firstReceive = false;
            // attempt reentrant call to withdrawAll to exploit mutant ordering
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            // ignore ok here
            return;
        }
        // On any subsequent receive (unexpected extra transfer), revert to signal detection
        revert("unexpected transfer");
    }
}

