    function testFuzz_property(uint256 depositAmount, bool useReentrant) public {
        // keep domain wide but sensible: non-zero deposit fits the scenario
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy an attacker helper that will reenter when receiving funds
        Attacker attacker = new Attacker(address(c));

        // fund the attacker externally so it can deposit
        vm.deal(address(attacker), depositAmount);

        // attacker deposits into C
        attacker.depositToC{value: depositAmount}();

        // If useReentrant is true, configure attacker to reenter during withdraw
        attacker.setReenter(useReentrant);

        // Now perform withdrawAll via the attacker which will trigger the low-level call
