pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // admissible domain: nonzero deposit amount and a nonzero, distinct depositor
        amt = bound(amt, 1, 1e30); // keep wide but nonzero
        vm.assume(depositor != address(0));

        // deploy a helper that always reverts when receiving funds
        Reverter rev = new Reverter();

        // fund the depositor so they can deposit
        vm.deal(depositor, amt);

        // make depositor deposit into c
        vm.prank(depositor);
        c.deposit{value: amt}();

        // sanity: the contract should have increased balance
        // now replace depositor with the Reverter as the caller for withdrawAll
        // we want to simulate the case where the external call to msg.sender reverts.
        // to do that, we need to make c believe msg.sender is the Reverter: we call withdrawAll from the reverter
        // but withdrawAll uses msg.sender as recipient; so we need to have the reverter invoke withdrawAll.

        // set up the reverter to call c.withdrawAll() when funded (so msg.sender for c.withdrawAll is the reverter)
        // give the reverter the permission/funds to trigger: we deploy it and then have depositor transfer its credit to reverter
        // Instead, we simulate: have depositor's credit recorded but have the reverter call withdrawAll — this models an attacker calling withdrawAll on behalf of the depositor address, so we need the mapping keyed by msg.sender: to match the depositor’s credit, the withdrawAll caller must be the same depositor. Thus we instead make the depositor be the Reverter contract address when depositing.

        // Alternative approach: deploy a contract that acts as depositor and reverts on receive; use it as depositor.
        RevertingDepositor rd = new RevertingDepositor(address(c));

        // fund the reverting depositor
        vm.deal(address(rd), amt);

        // have the reverting depositor deposit into c
        rd.depositToC{value: amt}();

        // Now attempt withdrawAll from the reverting depositor; this will cause the external call to revert
        bool ok;
        try rd.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a failing withdrawAll, the reference implementation preserves the depositor's recorded credit
        // (withdrawAll reverted, so state should be unchanged). We assert that c still records the same credit for that depositor.
        // Use the public getter for the mapping via a helper in C if available; mapping is private but we cannot access it directly.
        // However, we can observe address(c).balance: since withdrawAll reverted, the contract balance must remain equal to the deposited amount.
        // The reference always reverts the external call and thus the contract balance remains unchanged for this scenario; the mutant also reverts the external call but leaves internal credit nonzero — both keep contract balance the same, so we need a distinguishing assertion that the mutant breaks.

        // The distinguishing property: after a failed withdrawAll (external transfer reverted), both contracts revert the call; but in the reference the depositor's credit remains unchanged (still can withdraw later), while in the mutant, because zeroing was removed, if the external call had succeeded the credit would also remain; however the failing external call causes a revert so state must be unchanged. To create a difference we instead assert that a successful withdrawAll reduces address(c).balance by amt when the callee accepts funds. The mutant that omits zeroing will allow a second successful withdrawAll that also reduces balance again. So we perform two withdraws via an accepting depositor and assert that after two withdrawAll calls, reference's balance decreased by amt once (i.e., 0) while mutant would allow twice. But we cannot call mutant here; we craft the test to assert the reference behavior: after two withdraws, the contract balance is zero.

        // Therefore perform the accepting depositor scenario now using an AcceptingDepositor
        AcceptingDepositor ad = new AcceptingDepositor(address(c));
        vm.deal(address(ad), amt);
        // deposit
        ad.depositToC{value: amt}();
        // first withdraw should succeed
        bool ok1;
        try ad.callWithdrawAll() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // second withdraw should do nothing (no funds), so succeed but transfer 0; overall contract balance should be zero
        bool ok2;
        try ad.callWithdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Single assertion reading c: after deposit and two withdrawAll calls by an accepting depositor, address(c).balance == 0
        assertTrue(address(c).balance == 0);
    }
}

// Helper: a contract that reverts on receive and can interact with C
contract RevertingDepositor {
    C c;
    constructor(address _c) { c = C(_c); }
    // deposit into c
    function depositToC() external payable {
        c.deposit{value: msg.value}();
    }
    // call withdrawAll which will try to send ether to this contract and thus revert
    function callWithdrawAll() external {
        c.withdrawAll();
    }
    receive() external payable {
        revert("nope");
    }
}

// Helper: a contract that accepts funds and can interact with C
contract AcceptingDepositor {
    C c;
    constructor(address _c) { c = C(_c); }
    function depositToC() external payable {
        c.deposit{value: msg.value}();
    }
    function callWithdrawAll() external {
        c.withdrawAll();
    }
    receive() external payable {}
}

