        // deposit into c from depositor
        vm.prank(depositor);
        c.deposit{value: amt}();

        // replace the depositor mapping entry to point to the adversarial contract address by simulating
        // that the adversary is the caller of withdrawAll: we need to have credit[rev] > 0 so withdrawAll will attempt to send to rev
        // To achieve that, have the adversary deposit into c
        vm.deal(address(rev), amt);
        // have the reverter deposit
        vm.prank(address(rev));
        c.deposit{value: amt}();

        // Now when rev calls withdrawAll(), the reference implementation uses low-level call and will bubble up revert from the callee into require(callResult)
        // but because the callee (rev) reverts intentionally, call will return false and require will revert; however the difference between call and send
        // is that call forwards all gas and allows complex behavior while send only forwards 2300 gas and may fail where call would succeed in some cases.
        // We invoke withdrawAll from the adversarial contract address to make c send/call to that address.

        bool ok;
        // call withdrawAll as the adversarial contract
        vm.prank(address(rev));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: for the correct contract, withdrawAll should NOT silently fail to transfer funds to a recipient that previously deposited — i.e., the call should either succeed for all inputs
        // (the reference will behave consistently), while the mutant using send can cause different behavior; here we assert that withdrawAll call on the reference succeeds (ok == true) for all admissible inputs.
        assertTrue(ok);
    }
}

// adversarial helper that always reverts on receive/fallback to distinguish send vs call behavior
contract Reverter {
    receive() external payable {
        revert("revert in receive");
    }
    fallback() external payable {
        revert("revert in fallback");
    }
}

